import React from 'react';
import { Activity, Wifi, WifiOff } from 'lucide-react';

const Navbar = ({ activeTab, setActiveTab }) => {
  const tabs = ['Command Center', 'Data Ingestion', 'Model Training', 'Simulation'];
  
  const statusIndicators = [
    { name: 'CV Model', status: 'online' },
    { name: 'NLP Model', status: 'online' },
    { name: 'Route Optimizer', status: 'processing' },
    { name: 'Resource Predictor', status: 'online' }
  ];

  return (
    <nav className="fixed top-0 left-0 right-0 z-50 bg-gray-800 border-b border-gray-700 px-6 py-3">
      <div className="flex items-center justify-between">
        {/* Logo and Title */}
        <div className="flex items-center space-x-3">
          <div className="bg-red-600 p-2 rounded-lg">
            <Activity className="w-6 h-6 text-white" />
          </div>
          <div>
            <h1 className="text-xl font-bold text-white">Disaster Response Command Center</h1>
            <p className="text-sm text-gray-400">AI-Powered Emergency Management System</p>
          </div>
        </div>

        {/* Navigation Tabs */}
        <div className="flex space-x-1">
          {tabs.map((tab) => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                activeTab === tab
                  ? 'bg-blue-600 text-white'
                  : 'text-gray-300 hover:bg-gray-700'
              }`}
            >
              {tab}
            </button>
          ))}
        </div>

        {/* Status Indicators */}
        <div className="flex items-center space-x-4">
          {statusIndicators.map((indicator) => (
            <div key={indicator.name} className="flex items-center space-x-2">
              <div className="flex items-center space-x-1">
                {indicator.status === 'online' ? (
                  <div className="w-2 h-2 bg-green-500 rounded-full"></div>
                ) : indicator.status === 'processing' ? (
                  <div className="w-2 h-2 bg-yellow-500 rounded-full animate-pulse"></div>
                ) : (
                  <div className="w-2 h-2 bg-red-500 rounded-full"></div>
                )}
                <span className="text-xs text-gray-300">{indicator.name}</span>
              </div>
            </div>
          ))}
          <div className="text-xs text-gray-400">
            Last Update: 4:30:32 PM
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
